abstract class PaymentProcessor {
  double processingFee = 2.50;

  // What varies by payment method
  bool validatePayment(double amount);
  void processPayment(double amount);
  void sendReceipt();

  // What's common for all payment methods
  final void handlePayment(double amount) {
    if (validatePayment(amount)) {
      double total = amount + processingFee;
      processPayment(total);
      sendReceipt();
      logTransaction(total);
    }
  }

  void logTransaction(double amount) {
    print('Transaction logged: \$${amount.toStringAsFixed(2)}');
  }
}
